using System;using System.Data;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class AdvancedSearchPage:UserControl{TextBox q;ComboBox type,status;DataGridView grid;public AdvancedSearchPage(){if(!AppSession.Can("Candidates.View")){Controls.Add(Ui.Label(L.Fa?"دسترسی مجاز نیست":"Access denied",16,true));return;}Dock=DockStyle.Fill;BackColor=Theme.Background;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=70,Padding=new Padding(8),WrapContents=false};q=Ui.Text();q.Width=300;type=new ComboBox{Width=160,DropDownStyle=ComboBoxStyle.DropDownList};type.Items.AddRange(new object[]{L.Fa?"کارجویان":"Candidates",L.Fa?"فرصت‌های شغلی":"Jobs",L.Fa?"شرکت‌ها":"Companies"});type.SelectedIndex=0;status=new ComboBox{Width=150,DropDownStyle=ComboBoxStyle.DropDownList};status.Items.AddRange(new object[]{L.Fa?"همه وضعیت‌ها":"All statuses","Available","Open","Closed"});status.SelectedIndex=0;var b=Ui.Button(L.Fa?"جستجوی پیشرفته":"Advanced search");b.Click+=(s,e)=>LoadData();top.Controls.AddRange(new Control[]{q,type,status,b});grid=Ui.Grid();Controls.Add(grid);Controls.Add(top);LoadData();}void LoadData(){string term="%"+(q.Text??"").Trim()+"%";DataTable t;if(type.SelectedIndex==1)t=Database.Query("SELECT TOP 300 j.Id,j.Title,c.Name Company,j.City,j.EmploymentType,j.Status,j.CreatedAt FROM Jobs j LEFT JOIN Companies c ON c.Id=j.CompanyId WHERE (j.Title LIKE @q OR j.City LIKE @q OR c.Name LIKE @q) AND (@s='' OR j.Status=@s) ORDER BY j.Id DESC",new SqlParameter("@q",term),new SqlParameter("@s",status.SelectedIndex<=0?"":status.Text));else if(type.SelectedIndex==2)t=Database.Query("SELECT TOP 300 Id,Name,Industry,City,Email,Website,IsActive,CreatedAt FROM Companies WHERE Name LIKE @q OR Industry LIKE @q OR City LIKE @q ORDER BY Id DESC",new SqlParameter("@q",term));else t=Database.Query("SELECT TOP 300 Id,FullName,City,Education,PrimarySkill,ExperienceYears,Status,Email FROM Candidates WHERE FullName LIKE @q OR City LIKE @q OR PrimarySkill LIKE @q OR Email LIKE @q ORDER BY Id DESC",new SqlParameter("@q",term));grid.DataSource=t;}}}